-- Practitioner buildout Phase 2 (PD-5, PD-6, PD-12, TL-7): versioned quiz
-- banks for the multi-framework constitutional assessment. The bank is DATA,
-- not code: questions, option-to-dimension score vectors, population variants
-- (adult / child kid-quiz / pregnancy / elderly weights), red-flag axis
-- overrides, framework coefficient matrices, and disagreement rules all live
-- in the jsonb so (a) the compute engine in record-diagnostic-completion is
-- generic over the bank and (b) a quiz-version bump recomputes any stored
-- completion from its raw_responses against the exact bank it was taken
-- under (Lock #37 recompute discipline).
--
-- Instrument copy note: question wording is DRAFT pending the founder's
-- brand-voice pass (Lock #45 authority surface); the scoring architecture is
-- final per the Decisions Ledger.

CREATE TABLE IF NOT EXISTS public.quiz_banks (
  version    text PRIMARY KEY,
  title      text NOT NULL,
  bank       jsonb NOT NULL,
  active     boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.quiz_banks IS
  'Versioned multi-framework assessment banks (Phase 2). Root-tier clients read the active bank to render questions; the record-diagnostic-completion EF computes readings server-side from raw responses + the bank (single engine, no client drift).';

ALTER TABLE public.quiz_banks ENABLE ROW LEVEL SECURITY;

CREATE POLICY quiz_banks_root_read
  ON public.quiz_banks FOR SELECT
  TO authenticated
  USING (current_user_at_least('root'::text) AND active);

INSERT INTO public.quiz_banks (version, title, bank) VALUES
('mf-v1', 'Multi-Framework Constitutional Assessment v1', '{"version": "mf-v1", "title": "Multi-Framework Constitutional Assessment", "dimensions": ["temperature", "moisture", "tone", "vitality", "fluid", "agni", "stagnation", "stasis", "mobility", "frame"], "axis_dimensions": ["temperature", "moisture", "tone"], "balanced_band": 0.2, "secondary_margin": 0.15, "tcm_threshold": 0.25, "populations": {"adult": {"note": "Default instrument."}, "child": {"note": "Parent-administered observation variant (PD-12): kid_text replaces text; items without kid_text are skipped."}, "pregnancy": {"note": "pregnancy_weight multiplies each item''s contribution; fluid-retention items down-weighted (physiologic edema), menses item skipped."}, "elderly": {"note": "elderly_weight multiplies age-confounded items (sleep depth, morning heaviness)."}}, "citations": {"primary_text_citation": {"source_id": "S23", "author": "Cook, W.H.", "title": "The Physiomedical Dispensatory", "year": 1869, "url": "https://www.henriettes-herb.com/eclectic/cook/", "locator": "General therapeutic principles - tissue conditions of heat/cold, dryness/dampness, constriction/relaxation"}, "secondary_citation": {"source_id": "S21", "kind": "industry_textbook", "author": "Wood, M.", "title": "The Practice of Traditional Western Herbalism", "year": 2004, "publisher": "North Atlantic Books", "locator": "Terrain energetics - axis assessment in modern Western practice"}, "framework_secondary": {"ayurveda": {"source_id": "S03", "author": "Frawley D, Lad V", "title": "The Yoga of Herbs", "year": 1986, "locator": "Constitutional assessment - dosha discriminators"}, "tcm": {"source_id": "S04", "author": "Bensky D, Clavey S, Stoger E", "title": "Chinese Herbal Medicine: Materia Medica (3rd ed)", "year": 2004, "locator": "Pattern identification - constitutional signs"}}}, "questions": [{"id": "T1", "domain": "temperature", "text": "Compared to the people around you, how do you usually run?", "options": [{"label": "I''m always the warm one", "scores": {"temperature": 1}}, {"label": "Slightly warm", "scores": {"temperature": 0.5}}, {"label": "Neither warm nor cold", "scores": {"temperature": 0}}, {"label": "Slightly cool", "scores": {"temperature": -0.5}}, {"label": "I''m always the cold one", "scores": {"temperature": -1}}], "kid_text": "Compared to siblings or friends, this child usually feels..."}, {"id": "T2", "domain": "temperature", "text": "Your hands and feet, most days:", "options": [{"label": "Warm even in winter", "scores": {"temperature": 1}}, {"label": "Usually warm", "scores": {"temperature": 0.5}}, {"label": "It varies", "scores": {"temperature": 0}}, {"label": "Often cool", "scores": {"temperature": -0.5}}, {"label": "Cold even in summer", "scores": {"temperature": -1}}], "kid_text": "This child''s hands and feet, most days:"}, {"id": "T3", "domain": "temperature", "text": "In a warm room, you:", "options": [{"label": "Overheat quickly - flushed, need air", "scores": {"temperature": 1}}, {"label": "Get uncomfortable before others", "scores": {"temperature": 0.5}}, {"label": "Feel fine", "scores": {"temperature": 0}}, {"label": "Feel pleasantly cozy", "scores": {"temperature": -0.5}}, {"label": "Finally feel comfortable", "scores": {"temperature": -1}}], "kid_text": "In a warm room, this child:"}, {"id": "T4", "domain": "temperature", "text": "Your natural face color at rest:", "options": [{"label": "Ruddy or easily flushed", "scores": {"temperature": 1}}, {"label": "Warm-toned", "scores": {"temperature": 0.5}}, {"label": "Balanced", "scores": {"temperature": 0}}, {"label": "On the pale side", "scores": {"temperature": -0.5}}, {"label": "Pale or washed-out", "scores": {"temperature": -1}}], "kid_text": "This child''s natural face color:"}, {"id": "T5", "domain": "temperature", "text": "Cold drinks and cold weather:", "options": [{"label": "I crave them", "scores": {"temperature": 1}}, {"label": "I enjoy them", "scores": {"temperature": 0.5}}, {"label": "No strong feeling", "scores": {"temperature": 0}}, {"label": "I''d rather not", "scores": {"temperature": -0.5}}, {"label": "I avoid them - they go right through me", "scores": {"temperature": -1}}], "kid_text": "Cold drinks and cold weather - this child:"}, {"id": "T6", "domain": "temperature", "text": "Right now, do you have a fever, burning inflammation, or a hot, red swelling?", "options": [{"label": "Yes", "scores": {"temperature": 1}}, {"label": "No", "scores": {"temperature": 0}}], "kid_text": "Right now, does this child have a fever or a hot, red swelling?", "red_flag": {"option": 0, "force": {"temperature": 1.0}, "note": "Unambiguous acute heat sign forces the Hot pole regardless of aggregate."}}, {"id": "M1", "domain": "moisture", "text": "Your skin, most of the year:", "options": [{"label": "Oily or moist", "scores": {"moisture": 1}}, {"label": "Slightly oily", "scores": {"moisture": 0.5}}, {"label": "Comfortable", "scores": {"moisture": 0}}, {"label": "A little dry", "scores": {"moisture": -0.5}}, {"label": "Dry, flaky, or rough", "scores": {"moisture": -1}}], "kid_text": "This child''s skin, most of the year:"}, {"id": "M2", "domain": "moisture", "text": "Mucus and congestion:", "options": [{"label": "Often congested - nose, sinuses, or chest", "scores": {"moisture": 1}}, {"label": "Some congestion most weeks", "scores": {"moisture": 0.5}}, {"label": "Rarely think about it", "scores": {"moisture": 0}}, {"label": "Nose and throat run dry", "scores": {"moisture": -0.5}}, {"label": "Persistently dry nose, throat, or cough", "scores": {"moisture": -1}}], "kid_text": "Mucus and congestion - this child:"}, {"id": "M3", "domain": "moisture", "text": "Puffiness or water retention (ankles, fingers, under eyes):", "options": [{"label": "Noticeable most days", "scores": {"moisture": 1}}, {"label": "Sometimes", "scores": {"moisture": 0.5}}, {"label": "Rarely", "scores": {"moisture": 0}}, {"label": "Never - if anything I run lean and dry", "scores": {"moisture": -0.5}}], "kid_text": "Puffiness - this child:", "pregnancy_weight": 0.4}, {"id": "M4", "domain": "moisture", "text": "Thirst:", "options": [{"label": "Rarely thirsty", "scores": {"moisture": 0.5}}, {"label": "Ordinary thirst", "scores": {"moisture": 0}}, {"label": "Often thirsty", "scores": {"moisture": -0.5}}, {"label": "Constantly thirsty with a dry mouth", "scores": {"moisture": -1}}], "kid_text": "Thirst - this child:"}, {"id": "M5", "domain": "moisture", "text": "Your digestion tends toward:", "options": [{"label": "Loose, heavy, or sluggish stools", "scores": {"moisture": 0.7}}, {"label": "Comfortable and regular", "scores": {"moisture": 0}}, {"label": "Dry or hard stools", "scores": {"moisture": -1}}], "kid_text": "This child''s digestion tends toward:"}, {"id": "M6", "domain": "moisture", "text": "Do you currently have visible swelling that leaves a dent when pressed (pitting edema)?", "options": [{"label": "Yes", "scores": {"moisture": 1}}, {"label": "No", "scores": {"moisture": 0}}], "red_flag": {"option": 0, "force": {"moisture": 1.0}, "note": "Pitting edema forces the Damp pole."}, "pregnancy_weight": 0.4}, {"id": "N1", "domain": "tone", "text": "Your muscles at rest:", "options": [{"label": "Knotted - I hold tension in my neck, jaw, or shoulders", "scores": {"tone": 1}}, {"label": "Somewhat tight", "scores": {"tone": 0.5}}, {"label": "Comfortable", "scores": {"tone": 0}}, {"label": "Loose", "scores": {"tone": -0.5}}, {"label": "Soft or slack - weak grip, easy sprains", "scores": {"tone": -1}}], "kid_text": "This child''s body at rest:"}, {"id": "N2", "domain": "tone", "text": "Under stress, your body:", "options": [{"label": "Winds tighter - clenched jaw, braced shoulders", "scores": {"tone": 1}}, {"label": "Tightens somewhat", "scores": {"tone": 0.5}}, {"label": "Neither", "scores": {"tone": 0}}, {"label": "Goes flat and heavy", "scores": {"tone": -0.5}}, {"label": "Goes slack - checked out, collapsed", "scores": {"tone": -1}}], "kid_text": "Under stress, this child:"}, {"id": "N3", "domain": "tone", "text": "Which is more like you?", "options": [{"label": "Cramps and spasms - muscle cramps, colic, tension headaches", "scores": {"tone": 1}}, {"label": "A bit of both, mildly", "scores": {"tone": 0}}, {"label": "Looseness - things sag, leak, or give way easily", "scores": {"tone": -1}}], "kid_text": "Which is more like this child?"}, {"id": "N4", "domain": "tone", "text": "Falling asleep:", "options": [{"label": "Mind races and body won''t unwind", "scores": {"tone": 1}}, {"label": "Takes a while to let go", "scores": {"tone": 0.5}}, {"label": "Easy", "scores": {"tone": 0}}, {"label": "I drift off anywhere but wake unrefreshed", "scores": {"tone": -0.5}}], "kid_text": "Falling asleep, this child:"}, {"id": "N5", "domain": "tone", "text": "Your digestion under stress:", "options": [{"label": "Cramps or knots", "scores": {"tone": 1}}, {"label": "A little tight", "scores": {"tone": 0.5}}, {"label": "Unbothered", "scores": {"tone": 0}}, {"label": "Goes sluggish and heavy", "scores": {"tone": -0.5}}], "kid_text": "This child''s tummy under stress:"}, {"id": "N6", "domain": "tone", "text": "Your default posture and energy:", "options": [{"label": "Braced and upright - ready for action", "scores": {"tone": 1}}, {"label": "Engaged", "scores": {"tone": 0.5}}, {"label": "Relaxed", "scores": {"tone": 0}}, {"label": "Slumped or collapsed", "scores": {"tone": -1}}], "kid_text": "This child''s default posture:"}, {"id": "V1", "domain": "vitality", "text": "Your energy reserve:", "options": [{"label": "Robust - I recover fast and rarely run empty", "scores": {"vitality": 1}}, {"label": "Good most days", "scores": {"vitality": 0.5}}, {"label": "Adequate", "scores": {"vitality": 0}}, {"label": "Thin - mild exertion costs me", "scores": {"vitality": -0.5}}, {"label": "Depleted - I crash after small efforts", "scores": {"vitality": -1}}], "kid_text": "This child''s energy reserve:"}, {"id": "V2", "domain": "vitality", "text": "Your voice and presence:", "options": [{"label": "Strong, carries easily", "scores": {"vitality": 0.5}}, {"label": "Ordinary", "scores": {"vitality": 0}}, {"label": "Soft - talking tires me", "scores": {"vitality": -0.7}}, {"label": "Weak - I avoid speaking when tired", "scores": {"vitality": -1}}], "kid_text": "This child''s voice:"}, {"id": "V3", "domain": "vitality", "text": "Colds and bugs:", "options": [{"label": "Rarely catch anything", "scores": {"vitality": 0.7}}, {"label": "Average", "scores": {"vitality": 0}}, {"label": "Catch most of what goes around", "scores": {"vitality": -0.7}}, {"label": "Constantly sick, slow to recover", "scores": {"vitality": -1}}], "kid_text": "Colds and bugs - this child:"}, {"id": "V4", "domain": "vitality", "text": "Mornings:", "options": [{"label": "I spring up ready", "scores": {"vitality": 0.5}}, {"label": "Fine after a few minutes", "scores": {"vitality": 0}}, {"label": "Heavy - I need a long ramp", "scores": {"vitality": -0.5}}], "kid_text": "Mornings, this child:", "elderly_weight": 0.7}, {"id": "V5", "domain": "vitality", "text": "Sweating:", "options": [{"label": "Only with real exertion", "scores": {"vitality": 0.5}}, {"label": "Normal", "scores": {"vitality": 0}}, {"label": "I break into a sweat with no exertion at all", "scores": {"vitality": -1}}], "kid_text": "Sweating - this child:"}, {"id": "F1", "domain": "fluid", "text": "At night:", "options": [{"label": "Night sweats or heat that wakes me", "scores": {"fluid": -1}}, {"label": "Occasionally warm at night", "scores": {"fluid": -0.5}}, {"label": "Comfortable", "scores": {"fluid": 0.3}}], "kid_text": "At night, this child:", "pregnancy_weight": 0.7}, {"id": "F2", "domain": "fluid", "text": "Do you notice pallor, dizziness on standing, or brittle nails?", "options": [{"label": "Often", "scores": {"fluid": -1}}, {"label": "Sometimes", "scores": {"fluid": -0.5}}, {"label": "Rarely or never", "scores": {"fluid": 0.3}}], "kid_text": "Does this child look pale or get dizzy standing up?"}, {"id":